INSERT INTO `wp_posts` VALUES (195,15,'2026-10-13 07:23:51','2026-10-13 07:23:51','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://fenix-portal-main.local/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Start','','inherit','closed','closed','','2-revision-v1','','','2026-10-13 07:23:51','2026-10-13 07:23:51','',2,'http://fenix-portal-main.local/?p=195',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (197,15,'2026-10-13 07:29:04','2026-10-13 07:29:04','<!-- wp:paragraph -->\n<p>Välkommen till Fenix medlemsportal. Du måste vara inloggad för att kunna se de flesta sidorna. Kontakta <a href=\"mailto:susanne.eneroth@pinkdogmedia.se\" data-type=\"page\" data-id=\"183\">Susanne Eneroth</a> för att få inloggningsuppgifter</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like piña coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://fenix-portal-main.local/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Start','','inherit','closed','closed','','2-revision-v1','','','2026-10-13 07:29:04','2026-10-13 07:29:04','',2,'http://fenix-portal-main.local/?p=197',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (198,15,'2026-10-13 07:35:26','2026-10-13 07:35:26','<!-- wp:paragraph -->\n<p>Välkommen till Fenix medlemsportal. Du måste vara inloggad för att kunna se de flesta sidorna. Kontakta <a href=\"mailto:susanne.eneroth@pinkdogmedia.se\" data-type=\"page\" data-id=\"183\">Susanne Eneroth</a> för att få inloggningsuppgifter. Du kan inte själv registrera dig. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I medlemsportalen kan du redigera dina uppgifter under menyalternativet<strong> Din profil</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Under  Medlemmar->Alla medlemmar kan du se övriga medlemmars uppgifter.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Du kan se vilka events som är på gång och registrera eller avregistrera från event.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like piña coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://fenix-portal-main.local/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Start','','inherit','closed','closed','','2-revision-v1','','','2026-10-13 07:35:26','2026-10-13 07:35:26','',2,'http://fenix-portal-main.local/?p=198',0,'revision','',0);
