INSERT INTO `wp_posts` VALUES (205,1,'2026-10-13 10:21:00','2026-10-13 10:21:00','<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">Välkommen till Fenix medlemsportal. Du måste vara inloggad för att kunna se de flesta sidorna. Kontakta <a href=\"mailto:susanne.eneroth@pinkdogmedia.se\" data-type=\"page\" data-id=\"183\">Susanne Eneroth</a> för att få inloggningsuppgifter. Du kan inte själv registrera dig. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">I medlemsportalen kan du redigera dina uppgifter under menyalternativet<strong> Din profil</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">Under <strong> Medlemmar-&gt;<a href=\"http://fenix-portal-main.local/alla-anvandare/\" data-type=\"page\" data-id=\"44\">Alla medlemmar</a></strong><a href=\"http://fenix-portal-main.local/alla-anvandare/\" data-type=\"page\" data-id=\"44\"> </a>kan du se övriga medlemmars uppgifter.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">Du kan se vilka events som är på gång och registrera eller avregistrera från event.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">Du kan även hantera TFA (tack för affären) uppgifter.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\"></p>\n<!-- /wp:paragraph -->','Start','','inherit','closed','closed','','2-revision-v1','','','2026-10-13 10:21:00','2026-10-13 10:21:00','',2,'http://fenix-portal-main.local/?p=205',0,'revision','',0);
