INSERT INTO `wp_posts` VALUES (244,1,'2026-10-15 17:36:20','2026-10-15 17:36:20','<!-- wp:group {\"style\":{\"css\":\"maximum-width: 600px;\\nwidth:800px;\"},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group has-custom-css\"><!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">Välkommen till Fenix medlemsportal. Du måste vara inloggad för att kunna se de flesta sidorna. Kontakta <a href=\"mailto:susanne.eneroth@pinkdogmedia.se\" data-type=\"page\" data-id=\"183\">Susanne Eneroth</a> för att få inloggningsuppgifter. Du kan inte registrera dig  själv .</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">I medlemsportalen kan du redigera dina uppgifter under menyalternativet<strong> Din profil</strong>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">Under <strong>Medlemmar-&gt;<a href=\"http://fenix-portal-main.local/alla-anvandare/\" data-type=\"page\" data-id=\"44\">Alla medlemmar</a></strong><a href=\"http://fenix-portal-main.local/alla-anvandare/\" data-type=\"page\" data-id=\"44\"> </a>kan du se övriga medlemmars uppgifter.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"-10px\"}}}} -->\n<p style=\"margin-bottom:-10px\">Du kan se vilka events som är på gång och registrera eller avregistrera dig från event.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Du kan även hantera TFA (tack för affären) uppgifter.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Start','','inherit','closed','closed','','2-revision-v1','','','2026-10-15 17:36:20','2026-10-15 17:36:20','',2,'http://fenix-portal-main.local/?p=244',0,'revision','',0);
