INSERT INTO `wp_usermeta` VALUES (145,6,'last_name','Stibeck');
INSERT INTO `wp_usermeta` VALUES (146,6,'description','Jag är företagsmäklare på Mandaq och har 20 års branscherfarenhet. \r\n\r\nTack vare många tidigare år som egen företagare och företagsledare besitter jag en genuin förståelse för de utmaningar och möjligheter som företagare möter i sin vardag. Jag behandlar varje förmedlingsuppdrag som om det vore mitt eget. Kundens intresse och behov står naturligtvis i centrum.\r\n\r\nJag är angelägen om att mina kunder och uppdragsgivare känner sig trygga när jag vägleder dem genom beslutsprocessen. För mig som mäklare är att det är viktigt att kommunikationen med kunden är tydlig och rak för att bygga upp ett ömsesidigt förtroende mellan mig och kunden.\r\n\r\nOm du funderar på att sälja, är nyfiken på marknaden eller vill värdera din verksamhet – tveka inte att höra av dig till mig! Jag finns alltid tillgänglig för att hjälpa dig och att komma fram till ett optimalt avslut.');
