INSERT INTO `wp_usermeta` VALUES (170,7,'description','Ditt företag är ditt levebröd och bör vara där du fokuserar din tid. Vi är specialister på säkerhet, låt om ta hand om säkerheten så kan ni fokusera på er verksamhet.\r\n\r\nFörutom att säkra dina värderingar kan vi även stödja processer och generera data för din verksamhet. Vi är ledande inom AI-lösningar för säkerhet och drift.');
