INSERT INTO `wp_usermeta` VALUES (284,13,'description','Vi erbjuder kvalitativa helhetslösningar för er flytt med oslagbar service och support hela vägen både till företag och privatpersoner. Som kund har ni alltid samma kontaktperson när ni bokar våra flyttjänster och helhetslösningar.\r\n\r\nLuta er tillbaka och låt oss göra jobbet! Vi löser hela er flytt och ser till att ni får en bekväm och positiv upplevelse hela vägen.');
