INSERT INTO `wp_usermeta` VALUES (302,14,'description','Delumo är en digital marknadsföringsbyrå grundad 2014 som hjälper företag att synas mer och sälja mer med annonsering på Meta (Facebook och Instagram) Med över 12 års erfarenhet och mer än +600 hjälpta klienter vet vi vad som faktiskt fungerar, och vad som bara kostar pengar.\r\n\r\nVi jobbar inte med tomma löften eller quick fixes. Vi jobbar med strategi, data och annonser som ger verkliga resultat.\r\n\r\nOavsett om du vill generera fler leads, öka din försäljning eller bygga ett varumärke som syns, är vi byrån som tar ansvar för hela resan, från strategi till optimering.\r\n\r\nDelumo – Marknadsföring med fokus på resultat.');
