INSERT INTO `wp_usermeta` VALUES (440,17,'description','Strandberg Kapitalförvaltning är ett svenskt värdepappersbolag som erbjuder ett brett utbud av finansiella tjänster för både privatpersoner och företag.\r\n\r\nMed en tydlig vision att leverera en skräddarsydd och unik kapitalförvaltning fokuserar vi på att skapa långsiktiga lösningar som matchar våra kunders individuella mål och behov.');
