INSERT INTO `wp_usermeta` VALUES (458,18,'description','Corem äger, förvaltar och förädlar kommersiella fastighetsbestånd. Fastighetsbestånd innehåller ett brett utbud av kommersiella lokaler, geografiskt samlade i attraktiva lägen inom storstadsområden och på tillväxtorter.\r\n\r\nInom Corem har vi en gedigen erfarenhet av att förvalta och utveckla kommersiella lokaler, men framförallt av att skapa lokaler där våra kunder trivs och har rätt förutsättningar för att verksamheten ska kunna utvecklas, tillsammans med oss.\r\n\r\nLokal förvaltning med egen personal är vår kärna. Fastigheterna är samlade i attraktiva lägen i storstadsområden och på tillväxtorter där de förvaltas av vår kunniga och närvarande personal. Vi tror på närhet, engagemang och långa affärsrelationer. Kompletterad av vårt gedigna hållbarhetsarbete, utvalda mertjänster och långsiktiga fastighetsförädling, skapar vi fastigheter för framtiden.\r\n\r\nCorem är noterat på Nasdaq Stockholm, Large Cap.\r\nPå corem.se har vi samlat information om vår verksamhet. Om du vill veta mer om vår verksamhet, tveka inte att höra av dig.');
