INSERT INTO `wp_usermeta` VALUES (476,19,'description','Växtinredning är enkelt sätt att skapa en inspirerande arbetsmiljö. Vi kan hjälpa dig med allt från enstaka blommor till större arrangemang och växtinstallationer.\r\n\r\nHos oss kan du både hyra och köpa växter och vi erbjuder dessutom löpande skötsel av växterna. Vi utvecklar ständigt våra produkter för att kunna uppfylla våra kunders önskemål.');
